results = []

for item in _items:
    response = item["json"]

    parts = response.get("content", {}).get("parts", [])

    if len(parts) == 0:
        continue

    text = parts[0].get("text", "")

    results.append({
        "json": {
            "gemini_response": text,
            "status": "Gemini evaluation received"
        }
    })

return results

results = []

for item in _items:
    job = item["json"]
    raw = job.get("gemini_response") or ""

    # Python Legacy does not allow standard-library imports.
    # Extract values from Gemini's JSON-formatted response.

    def get_text(key):
        marker = '"' + key + '":'
        if marker not in raw:
            return ""

        part = raw.split(marker, 1)[1].strip()

        if not part.startswith('"'):
            return ""

        part = part[1:]
        output = ""
        escaped = False

        for ch in part:
            if escaped:
                output += ch
                escaped = False
            elif ch == "\\":
                escaped = True
            elif ch == '"':
                break
            else:
                output += ch

        return output

    # Match score
    score = None
    marker = '"match_score":'

    if marker in raw:
        part = raw.split(marker, 1)[1]
        number = part.split(",", 1)[0].strip()

        try:
            score = int(number)
        except:
            pass

    # Location eligibility can be a string or object
    eligibility = get_text("location_eligibility")

    if not eligibility:
        status = get_text("status")
        details = get_text("details")

        if status or details:
            eligibility = status + ": " + details

    if not eligibility:
        eligibility = "Unknown - verify eligibility"

    results.append({
        "json": {
            "title": job.get("title"),
            "company": job.get("company"),
            "location": job.get("location"),
            "application_url": job.get("url"),
            "description": job.get("description", ""),
            "match_score": score,
            "recommendation": get_text("recommendation"),
            "location_eligibility": eligibility,
            "reason": get_text("reason"),
            "source": job.get("source")
        }
    })

return results

# Rank jobs by CV-based match score

jobs = []

for item in _items:
    jobs.append(item["json"])

jobs.sort(
    key=lambda job: (
        job.get("match_score")
        if isinstance(job.get("match_score"), (int, float))
        else -1
    ),
    reverse=True
)

results = []

for index, job in enumerate(jobs):
    ranked_job = dict(job)
    ranked_job["rank"] = index + 1

    results.append({
        "json": ranked_job
    })

return results

